Q: Querying Business Central/NAV Item Availability by Location through OData or the API A: <p>I did it like this:</p>
<pre><code>codeunit 50134 &quot;Item Availability BCT&quot;
{
    trigger OnRun()
    var
        Item: Record Item;
    begin
        Item.FindSet();
        repeat
            Generate(Item);
        until Item.Next() = 0;
    end;

    procedure Generate(Item: Record Item)
    var
        TempPageData: Record &quot;Inventory Page Data&quot; temporary;
        ItemAvailability: Record &quot;Item Availability API BCT&quot;;
        CalcInventoryPageData: Codeunit &quot;Calc. Inventory Page Data&quot;;
        RunningInventory, RunningInventoryForecast, RunningInventoryPlan: Decimal;
    begin
        Item.SetRange(&quot;Drop Shipment Filter&quot;, false);

        CalcInventoryPageData.Initialize(Item, '', false, 0D, false);

        TempPageData.SetCurrentKey(&quot;Period Start&quot;, &quot;Line No.&quot;);
        CalcInventoryPageData.CreatePeriodEntries(TempPageData, 0);
        TempPageData.SetRange(Level, 0);
        if TempPageData.Find('-') then
            repeat
                CalcInventoryPageData.DetailsForPeriodEntry(TempPageData, true);
                CalcInventoryPageData.DetailsForPeriodEntry(TempPageData, false);
            until TempPageData.Next() = 0;
        TempPageData.SetRange(Level);

        ItemAvailability.SetRange(&quot;Item No.&quot;, Item.&quot;No.&quot;);
        ItemAvailability.DeleteAll();
        if TempPageData.Find('-') then
            repeat
                TempPageData.UpdateInventorys(RunningInventory, RunningInventoryForecast, RunningInventoryPlan);
                ItemAvailability.TransferFields(TempPageData);
                ItemAvailability.&quot;Item No.&quot; := Item.&quot;No.&quot;;
                ItemAvailability.Insert();
            until TempPageData.Next() = 0;
    end;
}
</code></pre>
